#!/usr/bin/env bash

set -euo pipefail
shopt -s inherit_errexit

PROG=${0##*/}
SELF=$0
DEF_UPSTREAM=https://github.com/wine-mirror/wine.git
DEF_TEST_GLOBS=('*/tests/*' 'include/wine/test.h')
SEP=$'\x1f' TAB=$'\t'

REGEN_RULES=(
    "server/protocol.def tools/make_requests|perl tools/make_requests|re-run tools/make_requests|include/wine/server_protocol.h server/request_trace.h server/request_handlers.h"
    "dlls/ntdll/ntdll.spec dlls/win32u/win32u.spec tools/make_specfiles|perl tools/make_specfiles|Automatically generated by tools/make_specfiles|dlls/ntdll/ntsyscalls.h dlls/win32u/win32syscalls.h"
    "dlls/ntoskrnl.exe/ntoskrnl.exe.spec dlls/hal/hal.spec tools/make_specfiles|perl tools/make_specfiles|ntoskrnl.exe.|dlls/win32k.sys/win32k.sys.spec"
)

if [[ -t 1 ]]; then
    C_G=$'\033[32m' C_Y=$'\033[33m' C_R=$'\033[31m' C_D=$'\033[2m' C_B=$'\033[1m' C_0=$'\033[0m'
else
    C_G='' C_Y='' C_R='' C_D='' C_B='' C_0=''
fi

note() { printf '%s%s:%s %s\n' "$C_B" "$PROG" "$C_0" "$*"; }
warn() { printf '%s%s: warning:%s %s\n' "$C_Y" "$PROG" "$C_0" "$*" >&2; }
die()  { printf '%s%s: error:%s %s\n' "$C_R" "$PROG" "$C_0" "$*" >&2; exit 1; }

if (( BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4) )); then
    die "bash 4.4 or newer is needed"
fi

usage() {
    cat <<EOF
usage: $PROG [options] FROM TO
       $PROG [options] --commits FILE
       $PROG [-C DIR] --continue | --skip | --abort | --status

Replays the upstream commits FROM..TO onto the checked-out branch of a Wine
tree, one at a time. Anything that doesn't apply cleanly is skipped, and an
incremental build runs after each applied commit, stopping at the first commit
that breaks it.

  FROM TO               upstream tags or commit ids, e.g. wine-10.0 wine-10.1
                        (tags are fetched from --upstream when not present)

Session:
      --continue        resume after a stop (rerunning with FROM TO does too)
      --skip            drop the commit that broke the build, then resume
      --abort           reset the branch to where the session started
      --status          show the current (or last) session
  -n, --dry-run         only report what would apply; changes nothing and
                        builds nothing (it does fetch, if needed)

What gets applied:
  -C, --repo DIR        the Wine tree (default: current directory)
  -u, --upstream URL    default: $DEF_UPSTREAM
      --commits FILE    pick the commits listed in FILE (one id per line)
                        instead of a range, e.g. the skipped.txt a finished
                        session leaves behind, after you've fixed a few by hand
      --no-fetch        FROM and TO must already exist locally
      --full-fetch      fetch upstream's whole history, not just the range
  -x, --exclude GLOB    leave out upstream changes to paths matching GLOB
                        (shell pattern on the full path, e.g. 'po/*';
                        repeatable)
      --include-tests   don't leave out test changes (new test directories
                        always come along; makedep needs them)
      --strict          exact-context patching like git am, instead of a
                        3-way merge (applies fewer commits)
      --no-regen        merge the protocol headers and syscall tables like any
                        other file instead of regenerating them
      --own-committer   record yourself as committer, like git am does
      --no-trailer      don't add the "(cherry picked from commit ...)" line

Building:
      --no-build        apply only
  -j, --jobs N          parallel jobs (default: number of CPUs)
      --make CMD        build command (default: gmake -jN, or make if there's
                        no gmake)
      --build-dir DIR   default: the tree itself (in-tree build)
      --configure CMD   run if the build dir has no Makefile (default:
                        ./configure)
      --baseline MODE   build before applying anything. clean: make clean and
                        a full build, to learn the warnings the tree already
                        has; make: incremental; none: don't. auto (default):
                        clean the first time, make after that
      --build-every N   build after every N applied commits instead of each
                        one; a batch that fails is retried one at a time
      --on-fail ACTION  stop (default), or skip a commit that breaks the build
      --stop-on-warning also stop when a commit adds new compiler warnings
  -v, --verbose         show the build output

State and logs: .git/upstream-pick/ (finished sessions under done/).
EOF
}

ACTION=run DRY=0
declare -A CLI=()
CLI_EXCL=() POS=()

parse_args() {
    local argv=("$@") i=0 opt val inline
    while (( i < ${#argv[@]} )); do
        opt=${argv[i]} val='' inline=0
        if [[ $opt == --*=* ]]; then val=${opt#*=} opt=${opt%%=*} inline=1; fi
        case $opt in
            -C|--repo|-u|--upstream|--commits|-x|--exclude|-j|--jobs|--make|\
            --build-dir|--configure|--baseline|--build-every|--on-fail)
                if (( ! inline )); then
                    (( i + 1 < ${#argv[@]} )) || die "$opt needs a value"
                    i=$(( i + 1 )) val=${argv[i]}
                fi ;;
            *)
                if (( inline )); then die "$opt doesn't take a value"; fi ;;
        esac
        case $opt in
            -C|--repo)         CLI[repo]=$val ;;
            -u|--upstream)     CLI[upstream]=$val ;;
            --commits)         CLI[commits]=$val ;;
            -x|--exclude)      CLI_EXCL+=("$val") ;;
            -j|--jobs)         CLI[jobs]=$val ;;
            -j[0-9]*)          CLI[jobs]=${opt#-j} ;;
            --make)            CLI[make]=$val ;;
            --build-dir)       CLI[build_dir]=$val ;;
            --configure)       CLI[configure]=$val ;;
            --baseline)        CLI[baseline]=$val ;;
            --build-every)     CLI[build_every]=$val ;;
            --on-fail)         CLI[on_fail]=$val ;;
            --no-fetch)        CLI[fetch]=no ;;
            --full-fetch)      CLI[fetch]=full ;;
            --include-tests)   CLI[tests]=keep ;;
            --strict)          CLI[mode]=strict ;;
            --no-regen)        CLI[regen]=0 ;;
            --own-committer)   CLI[keep_committer]=0 ;;
            --no-trailer)      CLI[trailer]=0 ;;
            --no-build)        CLI[build]=0 ;;
            --stop-on-warning) CLI[stop_on_warning]=1 ;;
            -v|--verbose)      CLI[verbose]=1 ;;
            -n|--dry-run)      DRY=1 ;;
            --continue)        ACTION='continue' ;;
            --skip)            ACTION=skip ;;
            --abort)           ACTION=abort ;;
            --status)          ACTION=status ;;
            -h|--help)         usage; exit 0 ;;
            --)                POS+=("${argv[@]:i+1}"); break ;;
            -*)                die "unknown option: $opt (see --help)" ;;
            *)                 POS+=("$opt") ;;
        esac
        i=$(( i + 1 ))
    done
}

ncpus() {
    nproc 2>/dev/null || getconf _NPROCESSORS_ONLN 2>/dev/null ||
        getconf NPROCESSORS_ONLN 2>/dev/null || echo 4
}
abspath() { if [[ $1 == /* ]]; then printf '%s\n' "$1"; else printf '%s/%s\n' "$PWD" "$1"; fi; }
trunc() { if (( ${#1} > $2 )); then printf '%s~' "${1:0:$2-1}"; else printf '%s' "$1"; fi; }
short() { printf '%.10s' "$1"; }

fmt_dur() {
    local s=$1
    if (( s >= 3600 )); then printf '%dh%02dm' $(( s / 3600 )) $(( s % 3600 / 60 ))
    elif (( s >= 60 )); then printf '%dm%02ds' $(( s / 60 )) $(( s % 60 ))
    else printf '%ds' "$s"; fi
}

first_and_count() {   # "a b c" -> "a +2"
    local f=()
    read -r -a f <<<"$1" || true
    if (( ${#f[@]} > 1 )); then printf '%s +%d' "${f[0]}" $(( ${#f[@]} - 1 ))
    elif (( ${#f[@]} )); then printf '%s' "${f[0]}"; fi
}

short_list() {   # paths... -> "a b c +N"
    local out="${*:1:3}"
    if (( $# > 3 )); then out+=" +$(( $# - 3 ))"; fi
    printf '%s' "$out"
}

load_kv() {   # file arrayname
    # shellcheck disable=SC2178
    local -n kv_=$2
    local line
    while IFS= read -r line || [[ -n $line ]]; do
        if [[ $line == *=* ]]; then kv_[${line%%=*}]=${line#*=}; fi
    done < "$1"
}

save_kv() {   # file arrayname
    # shellcheck disable=SC2178
    local -n kv_=$2
    local k
    for k in "${!kv_[@]}"; do printf '%s=%s\n' "$k" "${kv_[$k]}"; done > "$1.tmp"
    mv -f "$1.tmp" "$1"
}

cleanup() {
    if [[ -n ${TMP-} ]]; then rm -rf "$TMP"; fi
    if [[ -n ${LOCKED-} ]]; then rm -rf "$ROOT/lock"; fi
}

on_interrupt() {
    trap - INT TERM
    printf '\n' >&2
    if (( ! DRY )) && [[ -f ${SESS-}/vars ]]; then V[stopped]=interrupted; save_vars; fi
    warn "interrupted; resume with: $HINT --continue"
    exit 130
}

lock() {
    mkdir -p "$ROOT"
    if ! mkdir "$ROOT/lock" 2>/dev/null; then
        local pid
        pid=$(cat "$ROOT/lock/pid" 2>/dev/null || true)
        if [[ -n $pid ]] && kill -0 "$pid" 2>/dev/null; then
            die "another $PROG (pid $pid) is working on this tree"
        fi
        rm -rf "$ROOT/lock"
        mkdir "$ROOT/lock" || die "can't lock $ROOT"
    fi
    printf '%s\n' "$$" > "$ROOT/lock/pid"
    LOCKED=1
}

require_no_operation() {
    local f
    for f in rebase-merge rebase-apply CHERRY_PICK_HEAD MERGE_HEAD REVERT_HEAD BISECT_LOG; do
        if [[ -e $GITDIR/$f ]]; then die "a git operation is in progress ($f); finish or abort it first"; fi
    done
}

tracked_changes() {
    git update-index -q --refresh >/dev/null 2>&1 || true
    git diff-index --name-only HEAD --
}

require_clean() {
    local dirty
    dirty=$(tracked_changes)
    if [[ -n $dirty ]]; then
        die "uncommitted changes to tracked files; commit or stash them first:"$'\n'"$(printf '%s\n' "$dirty" | sed -n '1,10s/^/    /p')"
    fi
}

declare -A O=() V=() PICKED=() OURS_CACHE=()

setup() {
    local repo=${CLI[repo]:-.} oid
    if [[ -n ${CLI[build_dir]-} ]]; then CLI[build_dir]=$(abspath "${CLI[build_dir]}"); fi
    if [[ -n ${CLI[commits]-} ]]; then CLI[commits]=$(abspath "${CLI[commits]}"); fi
    TOP=$(git -C "$repo" rev-parse --show-toplevel 2>/dev/null) || die "not inside a git work tree: $repo"
    cd "$TOP"
    GITDIR=$(git rev-parse --absolute-git-dir)
    ROOT=$GITDIR/upstream-pick
    SESS=$ROOT/session
    KNOWN=$ROOT/known-warnings
    HINT="$(printf '%q' "$SELF") -C $(printf '%q' "$TOP")"
    oid=$(git rev-parse --verify -q HEAD) || die "$TOP has no commits yet"
    ZERO_OID=${oid//?/0}
    TMP=$(mktemp -d "${TMPDIR:-/tmp}/upstream-pick.XXXXXX")
}

set_options() {
    local insession=0 k
    O=([upstream]=$DEF_UPSTREAM [fetch]=shallow [mode]=merge [tests]=drop [regen]=1
       [keep_committer]=1 [trailer]=1 [excludes]='' [commits]=''
       [build]=1 [jobs]=$(ncpus) [make]='' [build_dir]='' [configure]=''
       [baseline]=auto [build_every]=1 [on_fail]=stop [stop_on_warning]=0 [verbose]=0)
    if (( ! DRY )) && [[ -f $SESS/config ]]; then insession=1; load_kv "$SESS/config" O; fi
    if (( ${#CLI_EXCL[@]} )); then CLI[excludes]=$(IFS=$SEP; printf '%s' "${CLI_EXCL[*]}"); fi
    for k in "${!CLI[@]}"; do
        if [[ $k == repo ]]; then continue; fi
        if (( insession )) && [[ ${CLI[$k]} != "${O[$k]}" ]] &&
           [[ " upstream fetch mode tests regen keep_committer trailer excludes commits build_dir " == *" $k "* ]]; then
            warn "'$k' can't change in the middle of a session; ignoring it"
            continue
        fi
        O[$k]=${CLI[$k]}
    done
    [[ ${O[jobs]} =~ ^[1-9][0-9]*$ ]] || die "--jobs wants a positive number"
    [[ ${O[build_every]} =~ ^[1-9][0-9]*$ ]] || die "--build-every wants a positive number"
    [[ ${O[on_fail]} =~ ^(stop|skip)$ ]] || die "--on-fail is stop or skip"
    [[ ${O[baseline]} =~ ^(auto|clean|make|none)$ ]] || die "--baseline is auto, clean, make or none"
}

derive() {
    local f
    BDIR=${O[build_dir]:-$TOP}
    if [[ -n ${O[make]} ]]; then
        MAKE_CMD=${O[make]}
    elif command -v gmake >/dev/null 2>&1; then
        MAKE_CMD="gmake -j${O[jobs]}"
    else
        MAKE_CMD="make -j${O[jobs]}"
    fi
    TEST_GLOBS=() USER_GLOBS=() GEN_FILES=() RULE_IN=() RULE_CMD=() RULE_OUT=()
    if [[ ${O[tests]} == drop ]]; then TEST_GLOBS=("${DEF_TEST_GLOBS[@]}"); fi
    if [[ -n ${O[excludes]} ]]; then IFS=$SEP read -r -a USER_GLOBS <<<"${O[excludes]}"; fi
    if [[ ${O[regen]} == 1 ]]; then
        local rule ins cmd marker outs act outv
        for rule in "${REGEN_RULES[@]}"; do
            IFS='|' read -r ins cmd marker outs <<<"$rule"
            if [[ ! -f ${cmd#perl } ]]; then continue; fi
            read -r -a outv <<<"$outs"
            act=''
            for f in "${outv[@]}"; do
                if [[ -f $f ]] && grep -qF "$marker" "$f"; then act+="${act:+ }$f" GEN_FILES+=("$f"); fi
            done
            if [[ -n $act ]]; then RULE_IN+=("$ins") RULE_CMD+=("$cmd") RULE_OUT+=("$act"); fi
        done
    fi
}

local_commit() {
    git rev-parse --verify -q "refs/upstream-pick/$1^{commit}" 2>/dev/null ||
        git rev-parse --verify -q "$1^{commit}" 2>/dev/null || true
}

remote_ref() {
    local name=$1 sha ref peeled='' plain='' head=''
    while read -r sha ref; do
        case $ref in
            "refs/tags/$name^{}") peeled=$sha ;;
            "refs/tags/$name")    plain=$sha ;;
            "refs/heads/$name")   head=$sha ;;
        esac
    done <<<"$2"
    if [[ -n $peeled ]]; then RREF=refs/tags/$name RSHA=$peeled
    elif [[ -n $plain ]]; then RREF=refs/tags/$name RSHA=$plain
    elif [[ -n $head ]]; then RREF=refs/heads/$name RSHA=$head
    elif [[ $name =~ ^[0-9a-f]{40}$ ]]; then RREF=$name RSHA=$name
    else die "${O[upstream]} has no tag or branch called '$name'"
    fi
}

resolve_range() {
    local from=$1 to=$2 f t ls fref tref url=${O[upstream]} step=256 rounds=0 before after shallow
    f=$(local_commit "$from") t=$(local_commit "$to")
    shallow=$(git rev-parse --git-path shallow)
    if [[ -n $f && -n $t && $f != "$t" ]] && git merge-base --is-ancestor "$f" "$t" 2>/dev/null; then
        FROM_SHA=$f TO_SHA=$t
        return 0
    fi
    [[ ${O[fetch]} != no ]] || die "$from..$to doesn't resolve locally (and --no-fetch was given)"
    note "fetching $from..$to from $url"
    ls=$(git ls-remote "$url") || die "git ls-remote $url failed"
    remote_ref "$from" "$ls"; fref=$RREF FROM_SHA=$RSHA
    remote_ref "$to" "$ls"; tref=$RREF TO_SHA=$RSHA
    if [[ ${O[fetch]} == full ]]; then
        local deep=()
        if [[ $(git rev-parse --is-shallow-repository) == true ]]; then deep=(--unshallow); fi
        git fetch --no-tags "${deep[@]}" "$url" "+$tref:refs/upstream-pick/$to" "+$fref:refs/upstream-pick/$from"
    elif [[ $(git rev-parse --is-shallow-repository) == false ]] && git cat-file -e "$FROM_SHA^{commit}" 2>/dev/null; then
        git fetch --no-tags "$url" "+$tref:refs/upstream-pick/$to"
    else
        if ! git cat-file -e "$TO_SHA^{commit}" 2>/dev/null; then
            git fetch --no-tags --depth=1 "$url" "+$tref:refs/upstream-pick/$to"
        fi
        until git merge-base --is-ancestor "$FROM_SHA" "$TO_SHA" 2>/dev/null; do
            rounds=$(( rounds + 1 ))
            before=$(cat "$shallow" 2>/dev/null || true)
            git fetch --no-tags --deepen=$step "$url" "+$tref:refs/upstream-pick/$to"
            after=$(cat "$shallow" 2>/dev/null || true)
            if [[ $before == "$after" ]] || (( rounds > 16 )); then
                die "$from doesn't seem to be an ancestor of $to"
            fi
            step=$(( step * 2 ))
        done
    fi
    git update-ref "refs/upstream-pick/$from" "$FROM_SHA"
    git update-ref "refs/upstream-pick/$to" "$TO_SHA"
    git merge-base --is-ancestor "$FROM_SHA" "$TO_SHA" || die "$from isn't an ancestor of $to"
}

load_picked() {
    local id
    PICKED=()
    while read -r id; do PICKED[$id]=1; done < <(
        git log --no-color --format=%B -F --grep='cherry picked from commit ' HEAD 2>/dev/null |
            sed -nE 's/.*cherry picked from commit ([0-9a-f]{40}).*/\1/p' || true)
}

save_vars() { save_kv "$SESS/vars" V; }

load_pending() {
    PEND=()
    if [[ -s $SESS/pending ]]; then mapfile -t PEND < "$SESS/pending"; fi
}

save_pending() {
    if (( ${#PEND[@]} )); then printf '%s\n' "${PEND[@]}"; fi > "$SESS/pending.tmp"
    mv -f "$SESS/pending.tmp" "$SESS/pending"
}

load_session() {
    load_kv "$SESS/vars" V
    mapfile -t QUEUE < "$SESS/queue"
    TOTAL=${#QUEUE[@]} NEXT=${V[next]} W=${#TOTAL}
    load_pending
    HEADC=$(git rev-parse HEAD)
}

start_session() {
    local from='' to='' name line id merges
    if [[ -n ${O[commits]} ]]; then
        [[ -r ${O[commits]} ]] || die "can't read ${O[commits]}"
        : > "$TMP/queue"
        while IFS= read -r line || [[ -n $line ]]; do
            line=${line%%#*} id=''
            read -r id _ <<<"$line" || true
            if [[ -z $id ]]; then continue; fi
            git rev-parse --verify -q "$id^{commit}" >> "$TMP/queue" ||
                die "${O[commits]} names a commit that isn't in this repository: $id"
        done < "${O[commits]}"
        name=commits-${O[commits]##*/}
    else
        if (( ${#POS[@]} != 2 )); then usage >&2; exit 2; fi
        from=${POS[0]} to=${POS[1]}
        resolve_range "$from" "$to"
        git rev-list --reverse --topo-order --no-merges "$TO_SHA" --not "$FROM_SHA" HEAD > "$TMP/queue" ||
            die "git rev-list $from..$to failed"
        merges=$(git rev-list --count --merges "$TO_SHA" --not "$FROM_SHA")
        if (( merges )); then
            warn "$from..$to has $merges merge commit(s); their changes come in through the commits they merge"
        fi
        name=$from..$to
    fi
    mapfile -t QUEUE < "$TMP/queue"
    TOTAL=${#QUEUE[@]} NEXT=0 W=${#TOTAL}
    if (( TOTAL == 0 )); then note "nothing to do: everything in $name is already in HEAD"; exit 0; fi
    mkdir -p "$SESS/logs"
    cp "$TMP/queue" "$SESS/queue"
    : > "$SESS/results"
    PEND=()
    save_pending
    HEADC=$(git rev-parse HEAD)
    V=([name]=$name [from]=$from [to]=$to [start]=$HEADC [branch]=$(git symbolic-ref -q HEAD || true)
       [started]=$(printf '%(%s)T' -1) [next]=0 [narrow]=-1 [good]=$HEADC [expected]=$HEADC
       [stopped]='' [dirty]=0 [build_now]=0 [baseline_done]=0 [baseline_cleaned]=0 [fail_log]='')
    if (( ! DRY )); then save_kv "$SESS/config" O; fi
    save_vars
    local where=${V[branch]#refs/heads/} dry=''
    if (( DRY )); then dry=' (dry run)'; fi
    note "$name: $TOTAL commits to replay onto ${where:-detached HEAD} at $(git rev-parse --short HEAD)$dry"
}

same_session() {
    if [[ -n ${CLI[commits]-} ]]; then [[ ${V[name]} == "commits-${CLI[commits]##*/}" ]]; return; fi
    [[ ${V[from]} == "${POS[0]-}" && ${V[to]} == "${POS[1]-}" ]]
}

reconcile_pending() {
    local cur=$1 keep=() line idx up loc subj det msgs subjs
    msgs=$(git log --no-color --format=%B "${V[good]}..$cur")
    subjs=$(git log --no-color --format=%s "${V[good]}..$cur")
    for line in "${PEND[@]}"; do
        IFS=$'\t' read -r idx up loc subj det <<<"$line"
        if git merge-base --is-ancestor "$loc" "$cur" 2>/dev/null ||
           [[ $msgs == *"cherry picked from commit $up"* || $'\n'$subjs$'\n' == *$'\n'"$subj"$'\n'* ]]; then
            keep+=("$line")
        else
            U_SUBJ=$subj
            record "$idx" dropped "$up" - "removed by hand"
        fi
    done
    PEND=("${keep[@]}")
    save_pending
}

resume_checks() {
    local cur branch
    require_no_operation
    branch=$(git symbolic-ref -q HEAD || true)
    [[ $branch == "${V[branch]}" ]] ||
        die "the session runs on ${V[branch]:-a detached HEAD}, but ${branch:-a detached HEAD} is checked out"
    require_clean
    cur=$(git rev-parse HEAD)
    if [[ $cur != "${V[expected]}" ]]; then
        git merge-base --is-ancestor "${V[good]}" "$cur" 2>/dev/null ||
            die "HEAD ($(short "$cur")) no longer contains $(short "${V[good]}"), the last commit that built; put it back, or --abort"
        note "HEAD moved since the stop; carrying on from $(short "$cur")"
        reconcile_pending "$cur"
        V[expected]=$cur V[build_now]=1 V[dirty]=1
    fi
    V[stopped]='' V[fail_log]=''
    save_vars
    HEADC=$cur
}

record() {
    printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$1" "$2" "$3" "$4" "$U_SUBJ" "$5" >> "$SESS/results"
    show "$1" "$2" "$3" "$5"
}

show() {
    local col=$C_D extra=''
    case $2 in
        applied) col=$C_G ;;
        conflict) col=$C_Y extra=$(first_and_count "$4") ;;
        broke|dropped) col=$C_R ;;
    esac
    printf '[%*d/%d] %s%-8s%s %.10s %s%s\n' "$W" $(( $1 + 1 )) "$TOTAL" "$col" "$2" "$C_0" "$3" \
        "$(trunc "$U_SUBJ" 62)" "${extra:+  $C_D($extra)$C_0}"
}

indent() { printf '%*s' $(( 2 * W + 4 )) ''; }

load_meta() {
    local line
    line=$(git log -1 --no-show-signature --no-color --date=raw \
        --format='%an%x1f%ae%x1f%ad%x1f%cn%x1f%ce%x1f%cd%x1f%s' "$1")
    IFS=$SEP read -r U_AN U_AE U_AD U_CN U_CE U_CD U_SUBJ <<<"$line"
    U_SUBJ=${U_SUBJ//$'\t'/ }
}

as_upstream() {
    GIT_AUTHOR_NAME=$U_AN GIT_AUTHOR_EMAIL=$U_AE GIT_AUTHOR_DATE=$U_AD \
    GIT_COMMITTER_NAME=$U_CN GIT_COMMITTER_EMAIL=$U_CE GIT_COMMITTER_DATE=$U_CD "$@"
}

drop_reason() {
    local g
    for g in "${GEN_FILES[@]}"; do if [[ $1 == "$g" ]]; then REASON=gen; return 0; fi; done
    for g in "${TEST_GLOBS[@]}"; do
        # shellcheck disable=SC2053
        if [[ $1 == $g ]]; then
            if [[ $2 == A* && $1 == */tests/* ]] && ! in_ours "${1%%/tests/*}/tests"; then return 1; fi
            REASON=tests
            return 0
        fi
    done
    # shellcheck disable=SC2053
    for g in "${USER_GLOBS[@]}"; do if [[ $1 == $g ]]; then REASON=user; return 0; fi; done
    return 1
}

in_ours() {
    if [[ -z ${OURS_CACHE[$1]-} ]]; then
        if git cat-file -e "$HEADC:$1" 2>/dev/null; then OURS_CACHE[$1]=1; else OURS_CACHE[$1]=0; fi
    fi
    [[ ${OURS_CACHE[$1]} == 1 ]]
}

classify() {
    local meta path omode osha st
    NCHANGED=0 NKEEP=0 NTESTS=0 NGEN=0 DROPPED=() OURS_CACHE=()
    : > "$TMP/drop.info"
    while IFS= read -r -d '' meta && IFS= read -r -d '' path; do
        NCHANGED=$(( NCHANGED + 1 ))
        read -r omode _ osha _ st <<<"${meta#:}"
        if ! drop_reason "$path" "$st"; then NKEEP=$(( NKEEP + 1 )); continue; fi
        case $REASON in
            tests) NTESTS=$(( NTESTS + 1 )) ;;
            gen) NGEN=$(( NGEN + 1 )) ;;
        esac
        DROPPED+=("$path")
        if [[ $st == A* ]]; then printf '0 %s\t%s\0' "$ZERO_OID" "$path"
        else printf '%s %s\t%s\0' "$omode" "$osha" "$path"; fi >> "$TMP/drop.info"
    done < <(git diff --raw -z --no-renames --no-abbrev --no-color "$1" "$2")
}

drop_note() {
    local nuser=$(( ${#DROPPED[@]} - NTESTS - NGEN )) s
    s="$nuser excluded path$( (( nuser == 1 )) || printf s)"
    if (( NTESTS && nuser )); then printf 'without test changes or %s' "$s"
    elif (( NTESTS )); then printf 'without test changes'
    elif (( nuser )); then printf 'without changes to %s' "$s"; fi
}

make_theirs() {
    local idx=$TMP/theirs.index tree
    if [[ ! -s $TMP/drop.info ]]; then THEIRS=$2; return 0; fi
    rm -f "$idx"
    GIT_INDEX_FILE=$idx git read-tree "$2"
    GIT_INDEX_FILE=$idx git update-index -z --index-info < "$TMP/drop.info"
    tree=$(GIT_INDEX_FILE=$idx git write-tree)
    THEIRS=$(as_upstream git commit-tree --no-gpg-sign "$tree" -p "$1" -m "upstream-pick: $2, filtered")
}

try_merge() {
    local out rc=0
    out=$(git merge-tree --write-tree --name-only --merge-base="$1" "$2" "$3" 2> "$TMP/merge.err") || rc=$?
    case $rc in
        0)  NEWTREE=${out%%$'\n'*}
            return 0 ;;
        1)  CONFLICT_FILES=$(printf '%s\n' "$out" | sed -n '2,/^$/p' | sed '/^$/d' | tr '\n' ' ')
            CONFLICT_FILES=${CONFLICT_FILES% }
            CONFLICT_INFO=$(printf '%s\n' "$out" | sed '1,/^$/d'; cat "$TMP/merge.err")
            return 1 ;;
        *)  die "git merge-tree failed on $3:"$'\n'"$(cat "$TMP/merge.err")" ;;
    esac
}

try_strict() {
    local idx=$TMP/strict.index
    rm -f "$idx"
    GIT_INDEX_FILE=$idx git read-tree "$2" || die "git read-tree $2 failed"
    git diff --binary --full-index -M --no-color --no-ext-diff --no-textconv "$1" "$3" > "$TMP/patch" ||
        die "git diff $1 $3 failed"
    if ! GIT_INDEX_FILE=$idx git apply --cached --whitespace=nowarn "$TMP/patch" 2> "$TMP/apply.err"; then
        CONFLICT_FILES=$(sed -nE -e 's/^error: patch failed: (.+):[0-9]+$/\1/p' \
            -e 's/^error: ([^:]+): (patch does not apply|does not exist in index|already exists in index).*/\1/p' \
            "$TMP/apply.err" | sort -u | tr '\n' ' ')
        CONFLICT_FILES=${CONFLICT_FILES% }
        CONFLICT_INFO=$(cat "$TMP/apply.err")
        return 1
    fi
    NEWTREE=$(GIT_INDEX_FILE=$idx git write-tree) || die "git write-tree failed"
}

create_commit() {
    local msg extra
    msg=$(git log -1 --no-show-signature --no-color --format=%B "$3")
    if [[ ${O[trailer]} == 1 ]]; then
        extra=$(drop_note)
        msg+=$'\n\n'"(cherry picked from commit $3${extra:+, $extra})"
    fi
    if [[ ${O[keep_committer]} == 1 ]]; then
        printf '%s\n' "$msg" | as_upstream git commit-tree "$1" -p "$2"
    else
        printf '%s\n' "$msg" |
            GIT_AUTHOR_NAME=$U_AN GIT_AUTHOR_EMAIL=$U_AE GIT_AUTHOR_DATE=$U_AD git commit-tree "$1" -p "$2"
    fi
}

checkout_commit() {
    git update-index -q --refresh >/dev/null 2>&1 || true
    if ! git read-tree -m -u --exclude-per-directory=.gitignore "$1" "$2" 2> "$TMP/rt.err"; then
        warn "couldn't update the work tree for $(short "$2"):"
        sed 's/^/    /' "$TMP/rt.err" >&2
        return 1
    fi
    if ! git update-ref -m "upstream-pick: $U_SUBJ" HEAD "$2" "$1"; then
        die "HEAD moved underneath $PROG; the index and work tree are at $2, HEAD isn't"
    fi
}

regen() {
    local k out tree newc ran=0 inv=() outv=() others=()
    for k in "${!RULE_CMD[@]}"; do
        read -r -a inv <<<"${RULE_IN[k]}"
        if git diff --quiet "$1" HEAD -- "${inv[@]}"; then continue; fi
        if ! out=$(eval "${RULE_CMD[k]}" 2>&1); then
            warn "${RULE_CMD[k]} failed:"
            printf '%s\n' "$out" | sed 's/^/    /' >&2
            return 1
        fi
        printf '%s %s: %s\n%s\n' "$(short "$2")" "$U_SUBJ" "${RULE_CMD[k]}" "$out" >> "$SESS/logs/regen.log"
        read -r -a outv <<<"${RULE_OUT[k]}"
        git add -- "${outv[@]}" || return 1
        ran=1
    done
    if (( ! ran )); then return 0; fi
    mapfile -t others < <(git diff --name-only)
    if (( ${#others[@]} )); then
        printf '  put back: %s\n' "${others[*]}" >> "$SESS/logs/regen.log"
        git checkout -q -- "${others[@]}" || return 1
    fi
    tree=$(git write-tree) || return 1
    if [[ $tree == "$(git rev-parse "HEAD^{tree}")" ]]; then return 0; fi
    newc=$(create_commit "$tree" "$1" "$2") || return 1
    git update-ref -m "upstream-pick: $U_SUBJ (regenerated)" HEAD "$newc" || return 1
}

process_commit() {
    local i=$1 c=${QUEUE[$1]} p before newc
    load_meta "$c"
    if [[ -n ${PICKED[$c]-} ]]; then record "$i" present "$c" - 'picked earlier'; return 0; fi
    if ! p=$(git rev-parse --verify -q "$c^1"); then record "$i" conflict "$c" - '(root commit)'; return 0; fi
    classify "$p" "$c"
    if (( NCHANGED == 0 )); then record "$i" present "$c" - 'empty upstream commit'; return 0; fi
    if (( NKEEP == 0 )); then
        if (( NTESTS == NCHANGED )); then record "$i" tests "$c" - ''
        else record "$i" excluded "$c" - "$(short_list "${DROPPED[@]}")"; fi
        return 0
    fi
    make_theirs "$p" "$c"
    if ! "try_${O[mode]}" "$p" "$HEADC" "$THEIRS"; then
        record "$i" conflict "$c" - "$CONFLICT_FILES"
        printf '=== [%d/%d] %s %s\n%s\n\n' $(( i + 1 )) "$TOTAL" "$c" "$U_SUBJ" "$CONFLICT_INFO" >> "$SESS/conflicts.log"
        return 0
    fi
    if [[ $NEWTREE == "$(git rev-parse "$HEADC^{tree}")" ]]; then
        record "$i" present "$c" - 'already in the tree'
        return 0
    fi
    newc=$(create_commit "$NEWTREE" "$HEADC" "$c")
    if (( DRY )); then
        HEADC=$newc
        record "$i" applied "$c" "$newc" "$(drop_note)"
        return 0
    fi
    before=$HEADC
    if ! checkout_commit "$before" "$newc"; then
        say_stop "fix that (often a stale generated file in the way), then: $HINT --continue"
        STOP=1; return 0
    fi
    if ! regen "$before" "$c"; then
        git reset -q --hard "$before"
        say_stop "the pick was undone; fix the generator (or use --no-regen), then: $HINT --continue"
        STOP=1; return 0
    fi
    HEADC=$(git rev-parse HEAD)
    V[expected]=$HEADC V[dirty]=1
    if [[ ${O[build]} == 1 ]]; then
        PEND+=("$i"$'\t'"$c"$'\t'"$HEADC"$'\t'"$U_SUBJ"$'\t'"$(drop_note)")
        save_pending
        show "$i" applied "$c" ''
    else
        record "$i" applied "$c" "$HEADC" "$(drop_note)"
    fi
}

say_stop() { printf '%s\n' "$*"; V[stopped]=error; save_vars; }

run_make() {
    if [[ ${O[verbose]} == 1 ]]; then
        ( cd "$BDIR" && eval "$MAKE_CMD" ) </dev/null 2>&1 | tee "$1"
        return "${PIPESTATUS[0]}"
    fi
    ( cd "$BDIR" && eval "$MAKE_CMD" ) </dev/null > "$1" 2>&1
}

warnings_in() {
    local esc=$'\033'
    { sed -e "s/${esc}\[[0-9;]*[mK]//g" "$1" | grep -E ': warning: ' | grep -vE '^g?make(\[[0-9]+\])?: ' || true; } |
        sed -E 's/:[0-9]+(:[0-9]+)?: warning: /: warning: /' | LC_ALL=C sort -u
}

new_warnings() {
    local cur=$TMP/warnings.cur n
    warnings_in "$1" > "$cur"
    if [[ ! -f $KNOWN ]]; then : > "$KNOWN"; fi
    LC_ALL=C comm -13 "$KNOWN" "$cur" > "$2"
    LC_ALL=C sort -u "$KNOWN" "$cur" -o "$KNOWN"
    n=$(wc -l < "$2"); n=${n//[!0-9]/}
    if (( n == 0 )); then rm -f "$2"; fi
    printf '%s' "$n"
}

show_errors() {
    local errs
    errs=$(grep -E 'error:|Error [0-9]+|undefined (reference|symbol)' "$1" | head -n 25 || true)
    if [[ -z $errs ]]; then errs=$(tail -n 25 "$1"); fi
    printf '%s\n' "$errs" | sed 's/^/    /'
    printf '  full log: %s\n' "$1"
}

ensure_configured() {
    local cmd=${O[configure]} log=$SESS/logs/configure.log
    if [[ -f $BDIR/Makefile ]]; then return 0; fi
    if [[ -z $cmd ]]; then
        if [[ $BDIR == "$TOP" ]]; then cmd=./configure; else cmd=$(printf '%q' "$TOP/configure"); fi
    fi
    note "$BDIR has no Makefile; running $cmd"
    mkdir -p "$BDIR"
    if ! ( cd "$BDIR" && eval "$cmd" ) </dev/null > "$log" 2>&1; then
        tail -n 20 "$log" | sed 's/^/    /' >&2
        die "configure failed; full log: $log"
    fi
}

baseline() {
    local mode=${O[baseline]} log=$SESS/logs/baseline.log t0=$SECONDS n
    if [[ ${V[baseline_done]} == 1 ]]; then return 0; fi
    ensure_configured
    if [[ $mode == auto ]]; then
        if [[ -f $KNOWN || ${V[baseline_cleaned]} == 1 ]]; then mode='make'; else mode='clean'; fi
    fi
    case $mode in
        none)
            note "baseline: skipped" ;;
        clean)
            note "baseline: make clean and a full build of $(git rev-parse --short HEAD), to learn the existing warnings"
            ( cd "$BDIR" && eval "$MAKE_CMD clean" ) </dev/null > "$SESS/logs/baseline-clean.log" 2>&1 || true
            V[baseline_cleaned]=1; save_vars ;;
        make)
            note "baseline: building $(git rev-parse --short HEAD) as it is" ;;
    esac
    if [[ $mode != none ]]; then
        if ! run_make "$log"; then
            show_errors "$log"
            die "the tree doesn't build before anything was applied; fix that first, then rerun"
        fi
        warnings_in "$log" > "$TMP/warnings.base"
        if [[ ! -f $KNOWN ]]; then : > "$KNOWN"; fi
        LC_ALL=C sort -u "$KNOWN" "$TMP/warnings.base" -o "$KNOWN"
        n=$(wc -l < "$KNOWN"); n=${n//[!0-9]/}
        note "baseline: ok in $(fmt_dur $(( SECONDS - t0 ))); $n known warning(s) won't be reported again"
    fi
    if [[ ! -f $KNOWN ]]; then : > "$KNOWN"; fi
    V[baseline_done]=1 V[good]=$(git rev-parse HEAD) V[dirty]=0
    save_vars
}

forget_results_from() {
    local line
    while IFS= read -r line; do
        if (( ${line%%$'\t'*} < $1 )); then printf '%s\n' "$line"; fi
    done < "$SESS/results" > "$SESS/results.tmp"
    mv -f "$SESS/results.tmp" "$SESS/results"
}

flush_pending() {
    local line idx up loc subj det last=$(( ${#PEND[@]} - 1 )) k=0
    for line in "${PEND[@]}"; do
        IFS=$'\t' read -r idx up loc subj det <<<"$line"
        if (( k == last && $1 )); then det+="${det:+; }+$1 warning$( (( $1 == 1 )) || printf s)"; fi
        printf '%s\tapplied\t%s\t%s\t%s\t%s\n' "$idx" "$up" "$loc" "$subj" "$det" >> "$SESS/results"
        k=$(( k + 1 ))
    done
    PEND=()
    save_pending
}

build_step() {
    local n=${#PEND[@]} idx up loc subj det first last label log wfile rc=0 t0=$SECONDS nnew what=''
    if (( n )); then
        IFS=$'\t' read -r last up loc subj det <<<"${PEND[n-1]}"
        IFS=$'\t' read -r first _ <<<"${PEND[0]}"
        label=$(printf '%04d-%.10s' $(( last + 1 )) "$up")
        if (( n > 1 )); then what=" ($n commits)"; fi
    else
        label=head-$(git rev-parse --short HEAD)
    fi
    log=$SESS/logs/$label.log wfile=$SESS/logs/$label.new-warnings
    if [[ -t 1 && ${O[verbose]} != 1 ]]; then printf '%s%smake ...%s' "$(indent)" "$C_D" "$C_0"; fi
    run_make "$log" || rc=$?
    if [[ -t 1 && ${O[verbose]} != 1 ]]; then printf '\r\033[K'; fi
    if (( rc == 0 )); then
        nnew=$(new_warnings "$log" "$wfile")
        if (( nnew )); then
            printf '%s%smake ok%s%s in %s, %s%d new warning(s)%s:\n' "$(indent)" "$C_G" "$C_0" "$what" \
                "$(fmt_dur $(( SECONDS - t0 )))" "$C_Y" "$nnew" "$C_0"
            sed -n "1,15s/^/$(indent)  /p" "$wfile"
        else
            printf '%s%smake ok%s%s in %s\n' "$(indent)" "$C_G" "$C_0" "$what" "$(fmt_dur $(( SECONDS - t0 )))"
            rm -f "$log"
        fi
        flush_pending "$nnew"
        V[good]=$(git rev-parse HEAD) V[dirty]=0 V[build_now]=0
        save_vars
        if (( nnew && O[stop_on_warning] )); then
            V[stopped]=warning; save_vars
            printf 'stopped on new warnings (listed in %s).\n' "$wfile"
            printf 'Fix them if you like (commit the fix), then: %s --continue\n' "$HINT"
            STOP=2
        fi
        return 0
    fi
    printf '%s%smake FAILED%s%s after %s\n' "$(indent)" "$C_R" "$C_0" "$what" "$(fmt_dur $(( SECONDS - t0 )))"
    if (( n > 1 )) && [[ $(git rev-parse HEAD) == "${V[expected]}" ]]; then
        note "that batch doesn't build; retrying its $n commits one at a time"
        git reset -q --keep "${V[good]}"
        PEND=(); save_pending
        forget_results_from "$first"
        NEXT=$first HEADC=${V[good]}
        V[next]=$first V[narrow]=$last V[expected]=${V[good]} V[dirty]=1
        save_vars
        return 0
    fi
    if (( n == 1 )) && [[ ${O[on_fail]} == skip && $(git rev-parse HEAD) == "${V[expected]}" ]]; then
        git reset -q --keep "${V[good]}"
        PEND=(); save_pending
        U_SUBJ=$subj
        record "$last" broke "$up" - "log: ${log#"$SESS"/}"
        HEADC=${V[good]} V[expected]=${V[good]} V[dirty]=1
        save_vars
        return 0
    fi
    show_errors "$log"
    V[stopped]=build V[fail_log]=$log
    save_vars
    if (( n == 1 )); then
        printf '\n%s broke the build: %s\n' "$(short "$up")" "$subj"
        printf '  Fix it (amend it, or commit a fix on top), then:  %s --continue\n' "$HINT"
        printf '  Or drop it and go on:                             %s --skip\n' "$HINT"
    else
        printf '\nthe build is broken; fix it, commit, then: %s --continue\n' "$HINT"
    fi
    printf '  Or put the branch back where it started:          %s --abort\n' "$HINT"
    STOP=1
}

run_loop() {
    local every dirty
    STOP=0
    if (( ! DRY )) && [[ ${O[build]} == 1 ]]; then
        note "building with '$MAKE_CMD' in $BDIR"
        baseline
        if (( ${#PEND[@]} )) || [[ ${V[build_now]} == 1 ]]; then
            build_step
            if (( STOP )); then return 0; fi
        fi
    fi
    while (( NEXT < TOTAL )); do
        if (( ! DRY )); then
            dirty=$(tracked_changes)
            if [[ -n $dirty ]]; then
                warn "tracked files have local changes (from the build?):"
                printf '%s\n' "$dirty" | sed -n '1,10s/^/    /p' >&2
                say_stop "commit or discard them, then: $HINT --continue"
                STOP=1; return 0
            fi
        fi
        trap '' INT TERM
        process_commit "$NEXT"
        trap on_interrupt INT TERM
        if (( STOP )); then return 0; fi
        NEXT=$(( NEXT + 1 ))
        V[next]=$NEXT
        save_vars
        if (( ! DRY )) && [[ ${O[build]} == 1 ]] && (( ${#PEND[@]} )); then
            every=${O[build_every]}
            if (( NEXT - 1 <= V[narrow] )); then every=1; fi
            if (( ${#PEND[@]} >= every || NEXT >= TOTAL )); then
                build_step
                if (( STOP )); then return 0; fi
            fi
        fi
    done
    if (( ! DRY )) && [[ ${O[build]} == 1 && ${V[dirty]} == 1 ]]; then
        build_step
    fi
}

declare -A CNT=()

tally() {
    local idx st rest
    CNT=()
    while IFS=$'\t' read -r idx st rest; do CNT[$st]=$(( ${CNT[$st]:-0} + 1 )); done < "$1"
}

print_counts() {
    local st desc
    for st in applied conflict broke dropped tests excluded present; do
        case $st in
            applied)  desc='' ;;
            conflict) desc="didn't apply cleanly" ;;
            broke)    desc='applied cleanly, but broke the build' ;;
            dropped)  desc='removed by hand after a failed build' ;;
            tests)    desc='touched nothing but tests' ;;
            excluded) desc='touched nothing but excluded paths' ;;
            present)  desc='already in the tree' ;;
        esac
        if (( ${CNT[$st]:-0} )); then printf '  %-9s %5d%s\n' "$st" "${CNT[$st]}" "${desc:+  $desc}"; fi
    done
}

report() {
    local idx st st2 up loc subj det
    printf '%s: %s onto %s\n' "$PROG" "${V[name]}" "${V[branch]:-detached HEAD}"
    printf 'started from %s, ended at %s\n\n' "${V[start]}" "$(git rev-parse HEAD)"
    tally "$1"
    print_counts
    for st in conflict broke dropped; do
        if (( ${CNT[$st]:-0} == 0 )); then continue; fi
        case $st in
            conflict) printf '\nDidn'"'"'t apply cleanly (conflicting files below each; details in conflicts.log):\n' ;;
            broke)    printf '\nBroke the build (logs in logs/):\n' ;;
            dropped)  printf '\nRemoved by hand:\n' ;;
        esac
        while IFS=$'\t' read -r idx st2 up loc subj det; do
            if [[ $st2 == "$st" ]]; then printf '  %.10s %s\n      %s\n' "$up" "$subj" "$det"; fi
        done < <(sort -t "$TAB" -k1,1n "$1")
    done
}

write_skipped() {
    local idx st up loc subj det
    {
        printf '# upstream commits %s skipped in %s\n' "$PROG" "${V[name]}"
        printf '# retry them with: %s --commits <this file>\n' "$HINT"
        while IFS=$'\t' read -r idx st up loc subj det; do
            case $st in conflict|broke|dropped) printf '%s  %s  (%s)\n' "$up" "$subj" "$st" ;; esac
        done < <(sort -t "$TAB" -k1,1n "$1")
    } > "$2"
}

finish() {
    local dest n=1 skipped
    printf '\n'
    tally "$SESS/results"
    if (( DRY )); then
        mkdir -p "$ROOT"
        report "$SESS/results" > "$ROOT/dry-run.txt"
        printf '%s (dry run) — of %d commits:\n' "${V[name]}" "$TOTAL"
        print_counts
        printf '\nfull list: %s\n' "$ROOT/dry-run.txt"
        return 0
    fi
    printf '%s: done with %s (%d commits):\n' "$PROG" "${V[name]}" "$TOTAL"
    print_counts
    report "$SESS/results" > "$SESS/report.txt"
    skipped=$(( ${CNT[conflict]:-0} + ${CNT[broke]:-0} + ${CNT[dropped]:-0} ))
    if (( skipped )); then write_skipped "$SESS/results" "$SESS/skipped.txt"; fi
    mkdir -p "$ROOT/done"
    dest=$ROOT/done/${V[name]//\//_}
    while [[ -e $dest ]]; do n=$(( n + 1 )); dest=$ROOT/done/${V[name]//\//_}-$n; done
    mv "$SESS" "$dest"
    printf '\nreport: %s/report.txt\n' "$dest"
    if (( skipped )); then
        printf 'after fixing some of the skipped ones by hand (git cherry-pick -x <id>), retry the rest:\n'
        printf '  %s --commits %s\n' "$HINT" "$(printf '%q' "$dest/skipped.txt")"
    fi
}

do_status() {
    local last
    if [[ ! -f $SESS/vars ]]; then
        # shellcheck disable=SC2012
        last=$(ls -1td "$ROOT"/done/*/ 2>/dev/null | head -n 1 || true)
        if [[ -n $last ]]; then
            note "no session in progress; the last one finished in ${last%/}"
            cat "${last%/}/report.txt" 2>/dev/null || true
        else
            note "no session in progress"
        fi
        return 0
    fi
    load_session
    printf '%s: %s onto %s, %d of %d commits done\n' "$PROG" "${V[name]}" "${V[branch]:-detached HEAD}" "$NEXT" "$TOTAL"
    printf '  started from %s, %s\n' "$(short "${V[start]}")" "$(printf '%(%F %R)T' "${V[started]}")"
    printf '  last good build at %s; HEAD is %s\n' "$(short "${V[good]}")" "$(git rev-parse --short=10 HEAD)"
    if [[ -n ${V[stopped]} ]]; then printf '  stopped: %s%s\n' "${V[stopped]}" "${V[fail_log]:+ (log: ${V[fail_log]})}"; fi
    if (( ${#PEND[@]} )); then printf '  applied, waiting for a build: %d commit(s)\n' "${#PEND[@]}"; fi
    printf '\n'
    tally "$SESS/results"
    print_counts
}

do_skip() {
    local cur idx up loc subj det
    [[ ${V[stopped]} == build ]] || die "nothing to skip: the session isn't stopped at a build failure"
    (( ${#PEND[@]} == 1 )) || die "expected one commit waiting on the build, found ${#PEND[@]}; fix and --continue instead"
    require_no_operation
    require_clean
    cur=$(git rev-parse HEAD)
    [[ $cur == "${V[expected]}" ]] ||
        die "HEAD moved since the stop; put it back (git reset --keep ${V[expected]}) or use --continue"
    IFS=$'\t' read -r idx up loc subj det <<<"${PEND[0]}"
    git reset -q --keep "${V[good]}"
    PEND=(); save_pending
    U_SUBJ=$subj
    record "$idx" broke "$up" - "log: ${V[fail_log]#"$SESS"/}"
    HEADC=${V[good]} V[expected]=${V[good]} V[stopped]='' V[fail_log]='' V[dirty]=1
    save_vars
}

do_abort() {
    local cur branch dest n=1
    [[ -f $SESS/vars ]] || die "there's no session to abort"
    load_kv "$SESS/vars" V
    require_no_operation
    require_clean
    branch=$(git symbolic-ref -q HEAD || true)
    [[ $branch == "${V[branch]}" ]] || die "the session runs on ${V[branch]:-a detached HEAD}; check that out first"
    cur=$(git rev-parse HEAD)
    git reset -q --keep "${V[start]}"
    mkdir -p "$ROOT/done"
    dest=$ROOT/done/${V[name]//\//_}-aborted
    while [[ -e $dest ]]; do n=$(( n + 1 )); dest=$ROOT/done/${V[name]//\//_}-aborted-$n; done
    mv "$SESS" "$dest"
    note "back at $(short "${V[start]}"); it was at $(short "$cur") ('git reset --keep $cur' brings that back)"
}

main() {
    local help
    parse_args "$@"
    setup
    trap cleanup EXIT
    trap on_interrupt INT TERM
    if (( DRY )); then SESS=$TMP/session; fi
    set_options
    derive
    if [[ ${O[mode]} == merge ]]; then
        help=$(git merge-tree -h 2>&1 || true)
        [[ $help == *merge-base* ]] ||
            die "$(git --version) lacks merge-tree --merge-base (needs 2.40); upgrade, or use --strict"
    fi
    if [[ ${O[keep_committer]} != 1 ]]; then
        git var GIT_COMMITTER_IDENT >/dev/null || die "set user.name and user.email first"
    fi
    case $ACTION in
        status)
            do_status
            return 0 ;;
    esac
    if (( DRY )); then
        [[ $ACTION == run ]] || die "--dry-run goes with FROM TO or --commits"
        start_session
        load_picked
        trap on_interrupt INT TERM
        run_loop
        finish
        return 0
    fi
    lock
    case $ACTION in
        abort)
            do_abort
            return 0 ;;
        skip|continue)
            [[ -f $SESS/vars ]] || die "there's no session to $ACTION"
            load_session
            if [[ $ACTION == skip ]]; then do_skip; else resume_checks; fi ;;
        run)
            if [[ -f $SESS/vars ]]; then
                load_session
                if (( ${#POS[@]} )) || [[ -n ${CLI[commits]-} ]]; then
                    same_session || die "${V[name]} is in progress; --continue it or --abort it first"
                fi
                note "resuming ${V[name]} at commit $(( NEXT + 1 )) of $TOTAL"
                resume_checks
            else
                if (( ${#POS[@]} == 0 )) && [[ -z ${O[commits]} ]]; then usage >&2; exit 2; fi
                require_no_operation
                require_clean
                start_session
            fi ;;
    esac
    load_picked
    trap on_interrupt INT TERM
    run_loop
    if (( STOP == 0 )); then finish; fi
    return "$STOP"
}

main "$@"
